//! Hand transcribed FFI to libvpl 2.16 (`libvpl.so.2`) and the libva calls the dma-buf path needs.
//! Sizes and field offsets are asserted against [`crate::layout`], generated by `cargo xtask layout
//! vpl`. Anonymous unions are modelled by the arm the code uses.

#![allow(non_snake_case, non_camel_case_types, non_upper_case_globals, dead_code)]

use std::ffi::{c_char, c_int, c_void};

pub type mfxU8 = u8;
pub type mfxU16 = u16;
pub type mfxI16 = i16;
pub type mfxU32 = u32;
pub type mfxI32 = i32;
pub type mfxU64 = u64;
pub type mfxI64 = i64;
pub type mfxHDL = *mut c_void;
pub type mfxMemId = *mut c_void;
/// `MFX_ERR_NONE` is 0, errors are negative, warnings positive.
pub type mfxStatus = c_int;
pub type mfxSession = *mut c_void;
pub type mfxSyncPoint = *mut c_void;
pub type mfxLoader = *mut c_void;
pub type mfxConfig = *mut c_void;

