#[repr(C)]
#[derive(Clone, Copy, Default, Debug, PartialEq, Eq)]
pub struct mfxVersion {
    pub Minor: u16,
    pub Major: u16,
}

#[repr(C)]
#[derive(Clone, Copy)]
pub struct mfxVariant {
    pub Version: u16,
    pub Type: c_int,
    pub U32: u32,
    pub pad: u32,
}

impl mfxVariant {
    pub const fn u32(v: u32) -> mfxVariant {
        mfxVariant { Version: MFX_VARIANT_VERSION, Type: MFX_VARIANT_TYPE_U32, U32: v, pad: 0 }
    }
}

