/// Every arm is plain integers, so any bit pattern is a value of every arm.
#[repr(C)]
#[derive(Clone, Copy)]
pub union mfxVideoParamUnion {
    pub mfx: mfxInfoMFX,
    pub dec: mfxInfoMFXDec,
    pub vpp: mfxInfoVPP,
}

#[repr(C)]
#[derive(Clone, Copy)]
pub struct mfxVideoParam {
    pub AllocId: u32,
    pub reserved: [u32; 2],
    pub reserved3: u16,
    pub AsyncDepth: u16,
    pub u: mfxVideoParamUnion,
    pub Protected: u16,
    pub IOPattern: u16,
    pub ExtParam: *mut *mut mfxExtBuffer,
    pub NumExtParam: u16,
    pub reserved2: u16,
}

impl mfxVideoParam {
    pub fn zeroed() -> mfxVideoParam {
        // SAFETY: integers and null pointers.
        unsafe { std::mem::zeroed() }
    }

    pub fn mfx(&self) -> &mfxInfoMFX {
        // SAFETY: plain integer arms.
        unsafe { &self.u.mfx }
    }
    pub fn mfx_mut(&mut self) -> &mut mfxInfoMFX {
        // SAFETY: plain integer arms.
        unsafe { &mut self.u.mfx }
    }
    pub fn dec(&self) -> &mfxInfoMFXDec {
        // SAFETY: plain integer arms.
        unsafe { &self.u.dec }
    }
    pub fn dec_mut(&mut self) -> &mut mfxInfoMFXDec {
        // SAFETY: plain integer arms.
        unsafe { &mut self.u.dec }
    }
    pub fn vpp(&self) -> &mfxInfoVPP {
        // SAFETY: plain integer arms.
        unsafe { &self.u.vpp }
    }
    pub fn vpp_mut(&mut self) -> &mut mfxInfoVPP {
        // SAFETY: plain integer arms.
        unsafe { &mut self.u.vpp }
    }
}

