    #[test]
    fn fourccs_and_ids_match_the_headers() {
        assert_eq!(MFX_FOURCC_NV12, 0x3231_564E);
        assert_eq!(MFX_FOURCC_P010, 0x3031_3050);
        assert_eq!(MFX_CODEC_HEVC, 0x4356_4548);
        assert_eq!(MFX_CODEC_AVC, 0x2043_5641);
        assert_eq!(MFX_EXTBUFF_CODING_OPTION2, 0x324F_4443);
        assert_eq!(VA_FOURCC_NV12, MFX_FOURCC_NV12);
        // 16 + 4 objects of 16 + 4 + 4 layers of 56, padded to 8.
        assert_eq!(size_of::<VADRMPRIMESurfaceDescriptor>(), 312);
        assert_eq!(size_of::<VASurfaceAttrib>(), 24);
    }
